function minSwaps(nums) {
  const digitSum = (x) => {
    let sum = 0;
    while (x > 0) {
      sum += x % 10;
      x = Math.floor(x / 10);
    }
    return sum;
  };
  const order = nums.map((value, index) => [digitSum(value), value, index]);
  order.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
  const visited = new Array(nums.length).fill(false);
  let swaps = 0;
  for (let start = 0; start < nums.length; start++) {
    if (visited[start]) continue;
    let length = 0;
    for (let i = start; !visited[i]; i = order[i][2]) {
      visited[i] = true;
      length++;
    }
    swaps += length - 1;
  }
  return swaps;
}

