function minSwaps(nums) {
  // Build the target with a string digit sum, then fix the positions left to right, swapping the right value in.
  const key = (x) => String(x).split('').reduce((total, digit) => total + Number(digit), 0);
  const target = [...nums].sort((a, b) => (key(a) !== key(b) ? key(a) - key(b) : a - b));
  const current = [...nums];
  let swaps = 0;
  for (let i = 0; i < current.length; i++) {
    if (current[i] === target[i]) continue;
    const j = current.indexOf(target[i], i + 1);
    [current[i], current[j]] = [current[j], current[i]];
    swaps++;
  }
  return swaps;
}

