function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? 2000 : pick(1, 8);
  const mode = pick(0, 2);
  // Narrow ranges give many equal digit sums, so ties are often broken by value.
  const high = mode === 0 ? 1000000000 : large ? 30000 : 60;
  const seen = new Set();
  while (seen.size < n) seen.add(pick(1, high));
  const nums = [...seen];
  if (mode === 2) {
    // Nearly in target order: sort by digit sum and value, then make a few random swaps.
    const key = (x) => String(x).split('').reduce((total, digit) => total + Number(digit), 0);
    nums.sort((a, b) => key(a) - key(b) || a - b);
    for (let t = pick(0, large ? 20 : 2); t > 0; t--) {
      const i = pick(0, n - 1);
      const j = pick(0, n - 1);
      [nums[i], nums[j]] = [nums[j], nums[i]];
    }
  }
  return [nums];
}
